def has_close_elements(numbers: List[float], threshold: float) -> bool:
    if len(numbers) < 2:
        return False
    sorted_nums = sorted(numbers)
    for i in range(1, len(sorted_nums)):
        if abs(sorted_nums[i] - sorted_nums[i - 1]) < threshold:
            return True
    return False

def separate_paren_groups(paren_string: str) -> List[str]:
    s = paren_string.replace(' ', '')
    result = []
    depth = 0
    start = None
    for i, ch in enumerate(s):
        if ch == '(':
            if depth == 0:
                start = i
            depth += 1
        elif ch == ')':
            depth -= 1
            if depth == 0 and start is not None:
                result.append(s[start:i+1])
                start = None
    return result

def truncate_number(number: float) -> float:
    """Return the decimal part of a positive floating point number."""
    return number - int(number)

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def mean_absolute_deviation(numbers: List[float]) -> float:
    if not numbers:
        return 0.0
    mean = sum(numbers) / len(numbers)
    return sum(abs(x - mean) for x in numbers) / len(numbers)

def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    for idx in range(n - 1, -1, -1):
        a, b, g, k = carpets[idx]
        if a <= x <= a + g and b <= y <= b + k:
            return idx + 1
    return -1

def find_number_combinations():
    combos = []
    for n in range(123, 1000):
        s = str(n)
        if '0' in s or len(set(s)) != 3:
            continue
        n2 = n * 2
        n3 = n * 3
        if n2 >= 1000 or n3 >= 1000:
            continue
        s2 = str(n2)
        s3 = str(n3)
        if '0' in s2 or '0' in s3:
            continue
        if len(set(s2)) != 3 or len(set(s3)) != 3:
            continue
