def verify_isbn(isbn: str) -> str:
    # Remove hyphens to get the 10 characters
    digits = isbn.replace('-', '')
    if len(digits) != 10:
        raise ValueError("ISBN must have 10 digits (including possible 'X')")
    # Convert first 9 digits to integers
    try:
        first_nine = [int(ch) for ch in digits[:9]]
    except ValueError:
        raise ValueError("ISBN must contain digits in the first 9 positions")
    # Convert last character to value (10 if 'X')
    last_char = digits[9]
    if last_char == 'X':
        last_val = 10
    else:
        try:
            last_val = int(last_char)
        except ValueError:
            raise ValueError("ISBN last character must be a digit or 'X'")
    # Compute checksum
    checksum = sum((i + 1) * first_nine[i] for i in range(9)) % 11
    if checksum == last_val:
        return "Right"
    # Determine correct checksum character
    correct_char = 'X' if checksum == 10 else str(checksum)
    # Replace last part after the last hyphen
    last_hyphen = isbn.rfind('-')
    if last_hyphen == -1:
        # No hyphens, just replace last character
        return isbn[:-1] + correct_char
    return isbn[:last_hyphen + 1] + correct_char

def process_random_numbers(numbers: list[int]) -> tuple[int, list[int]]:
