    return len(unique_numbers), unique_numbers

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        # Determine sign
        if not terms:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'
        abs_coeff = abs(coeff)
        # Determine variable part
        if degree == 0:
            var = ''
        elif degree == 1:
            var = 'x'
        else:
            var = f'x^{degree}'
        # Determine coefficient string
        if abs_coeff == 1 and degree != 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)
        terms.append(f"{sign}{coeff_str}{var}")
    return ''.join(terms) if terms else '0'

def largest_prime_factor(n: int) -> int:
    i = 2
    while i * i <= n:
        if n % i == 0:
            return n // i
        i += 1
    return n

def count_coprime_pairs(x0: int, y0: int) -> int:
    if x0 <= 0 or y0 <= 0:
        return 0
    if y0 % x0 != 0:
        return 0
    n = y0 // x0

    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    limit = int(n ** 0.5)
    for i in range(1, limit + 1):
        if n % i == 0:
            a = i
            b = n // i
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque
    if A == B:
        return 0
    max_steps = 10
    visited = {A}
    queue = deque([(A, 0)])
    while queue:
        current, steps = queue.popleft()
        if steps >= max_steps:
            continue
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1
    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque
    # Convert rules to a dictionary mapping each digit to a list of possible replacements
    rule_map = {}
    for x, y in rules:
        rule_map.setdefault(x, []).append(y)

    visited = set([n])
    queue = deque([n])

    while queue:
        current = queue.popleft()
        s = str(current)
        for i, ch in enumerate(s):
            d = int(ch)
            if d in rule_map:
                for y in rule_map[d]:
                    new_s = s[:i] + str(y) + s[i+1:]
                    new_num = int(new_s)
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)
    return len(visited)

def calculate_score(system: int, points: str) -> list:
    scores = []
    player = 0
    opponent = 0
    for p in points:
        if p == 'W':
            player += 1
        elif p == 'L':
            opponent += 1
        else:
            continue  # ignore any other characters
        if (player >= system or opponent >= system) and abs(player - opponent) >= 2:
            scores.append(f"{player}:{opponent}")
            player = 0
            opponent = 0
    if player > 0 or opponent > 0:
        scores.append(f"{player}:{opponent}")
    return scores

